    return true;
  });
  assert.deepEqual(f.events.map(({ type, x, y }) => [type, x, y]), [['mouseMoved', 169.5, 178]]);
  assert.equal(f.counts().reads, kind === 'owner' ? 4 : 5);
  assert.equal(f.counts().owned, 6);
});

